def compute(vars):
    years_below_threshold = []
    if vars["v1"] < 100000:
        years_below_threshold.append(2019)
    if vars["v2"] < 100000:
        years_below_threshold.append(2018)

    value = years_below_threshold[0] if years_below_threshold else None
    return {
        "value": value,
        "trace": {
            "threshold": 100000,
            "years_below_threshold": years_below_threshold,
            "output_meta": {"currency": None, "scale": None, "unit": "year"}
        }
    }
